# AUTOGENERATED FILE
from pymol import cmd
import os
import re

# Global variables
current_index = 0
if "current_path" not in globals():
    current_path = "."
loaded_steps = []
bucket_index = 0
bucket_size = 10
reg_pattern = r"^.+pdb|.+cif$"
pinned_objects = set()  # 固定的对象集合
auto_bucket_mode = True  # 自动bucket模式
switch_commands = []  # 切换object时要执行的命令列表


def load_by_bucket(path="."):
    """
    DESCRIPTION
    Load PDB files in the specified directory in groups.
    PARAMETERS
    path: str - The directory path containing PDB files (default: current directory).
    bucket_size: int - The number of files to load in each group (default: 10).
    pattern: str - The regex pattern to match PDB files (default: match all PDB files).
    """
    global bucket_index, current_path, current_index, bucket_size, reg_pattern, pinned_objects
    files = os.listdir(path)
    pattern = re.compile(reg_pattern)
    pdb_files = [file for file in files if pattern.match(file)]

    pdb_files.sort()

    while True:
        grp_indexes = [i for i in range(0, len(pdb_files), bucket_size)]
        # 只删除非固定对象
        all_objects = cmd.get_object_list()
        for obj in all_objects:
            if obj not in pinned_objects:
                cmd.delete(obj)

        if bucket_index >= len(grp_indexes):
            bucket_index = 0
        if bucket_index < 0:
            bucket_index = len(grp_indexes) - 1
        grp_idx = grp_indexes[bucket_index]
        group_files = pdb_files[grp_idx : grp_idx + bucket_size]
        for file in group_files:
            obj_name = file.replace(".pdb", "").replace(".cif", "")
            if obj_name not in cmd.get_object_list():
                cmd.load(os.path.join(path, file))
        current_index = 0

        # 禁用所有非固定对象，只启用第一个
        all_loaded = cmd.get_object_list()
        non_pinned = [obj for obj in all_loaded if obj not in pinned_objects]
        if non_pinned:
            cmd.disable("all")
            # 重新启用固定对象
            for pinned in pinned_objects:
                if pinned in cmd.get_object_list():
                    cmd.enable(pinned)
            cmd.enable(non_pinned[0])
        yield 1


def setup_loader(path=None, pattern=r"^.+pdb$", group_size: int = None):
    """
    DESCRIPTION
    """
    global current_path, bucket_loader, bucket_size, reg_pattern
    if path is not None:
        current_path = path

    if group_size is not None:
        bucket_size = int(group_size)

    if pattern is not None and pattern != reg_pattern:
        reg_pattern = pattern

    bucket_loader = load_by_bucket(current_path)


@cmd.set_key("CTRL-right")
def next_bucket(path=None):
    """
    DESCRIPTION
    Load the next group of PDB files.
    """
    global current_path, bucket_loader, bucket_index
    if current_path == "." and path is None:
        raise Exception(
            "No path specified, please run `setup_loader` with a path argument first"
        )

    if path is not None:
        current_path = path

    if "bucket_loader" not in globals():
        bucket_loader = load_by_bucket(current_path)
    bucket_index += 1
    try:
        next(bucket_loader)
    except StopIteration:
        bucket_loader = load_by_bucket(current_path)
        next(bucket_loader)


@cmd.set_key("CTRL-left")
def prev_bucket(path=None):
    """
    DESCRIPTION
    Load the previous group of PDB files.
    """
    global current_path, bucket_loader, bucket_index
    if current_path == "." and path is None:
        raise Exception(
            "No path specified, please run `setup_loader` with a path argument first"
        )

    if path is not None:
        current_path = path

    if "bucket_loader" not in globals():
        bucket_loader = load_by_bucket(current_path)
    bucket_index -= 1
    try:
        next(bucket_loader)
    except StopIteration:
        bucket_loader = load_by_bucket(current_path)
        next(bucket_loader)


def smart_step_forward():
    """
    智能前进：到达当前bucket末尾时自动加载下一个bucket
    """
    global current_index, loaded_steps, step_generator, auto_bucket_mode, bucket_loader

    loaded_steps = [obj for obj in cmd.get_object_list() if obj not in pinned_objects]
    if not loaded_steps:
        raise Exception("No non-pinned objects loaded")

    refresh_current_idx()
    current_index += 1

    # 如果到达当前bucket末尾且开启自动模式
    if current_index >= len(loaded_steps) and auto_bucket_mode:
        print("Reached end of current bucket, loading next...")
        next_bucket()
        loaded_steps = [
            obj for obj in cmd.get_object_list() if obj not in pinned_objects
        ]
        current_index = 0
    elif current_index >= len(loaded_steps):
        current_index = 0

    if "step_generator" not in globals():
        step_generator = take_step()
    next(step_generator)


def smart_step_backward():
    """
    智能后退：到达当前bucket开头时自动加载前一个bucket
    """
    global current_index, loaded_steps, step_generator, auto_bucket_mode, bucket_loader

    loaded_steps = [obj for obj in cmd.get_object_list() if obj not in pinned_objects]
    if not loaded_steps:
        raise Exception("No non-pinned objects loaded")

    refresh_current_idx()
    current_index -= 1

    # 如果到达当前bucket开头且开启自动模式
    if current_index < 0 and auto_bucket_mode:
        print("Reached beginning of current bucket, loading previous...")
        prev_bucket()
        loaded_steps = [
            obj for obj in cmd.get_object_list() if obj not in pinned_objects
        ]
        current_index = len(loaded_steps) - 1
    elif current_index < 0:
        current_index = len(loaded_steps) - 1

    if "step_generator" not in globals():
        step_generator = take_step()
    next(step_generator)


def pin_current(selection=None):
    """
    DESCRIPTION
    Pin the currently enabled object(s) so they won't be deleted when switching buckets.
    PARAMETERS
    selection: str - PyMOL selection string. If None, pin all enabled objects.
    """
    global pinned_objects

    if selection is None:
        # 默认获取所有enabled的对象
        enabled_objects = cmd.get_names("objects", 0, selection="(enabled)")
        objects_to_pin = [obj for obj in enabled_objects if obj not in pinned_objects]
    else:
        # 使用指定的selection
        try:
            selected_objects = cmd.get_names("objects", selection=selection)
            objects_to_pin = [
                obj for obj in selected_objects if obj not in pinned_objects
            ]
        except:
            print(f"Invalid selection: {selection}")
            return

    if objects_to_pin:
        for obj_to_pin in objects_to_pin:
            pinned_objects.add(obj_to_pin)

        if len(objects_to_pin) == 1:
            print(f"Pinned object: {objects_to_pin[0]}")
        else:
            print(f"Pinned objects: {objects_to_pin}")
        print(f"Currently pinned objects: {list(pinned_objects)}")
    else:
        if selection is None:
            print("No unpinned enabled objects found")
        else:
            print(f"No unpinned objects found in selection: {selection}")


def unpin_current():
    """
    DESCRIPTION
    Unpin the currently enabled object.
    """
    global pinned_objects
    enabled_objects = cmd.get_names("objects", 0, selection="(enabled)")
    current_objects = [obj for obj in enabled_objects if obj in pinned_objects]

    if current_objects:
        obj_to_unpin = current_objects[0]
        pinned_objects.discard(obj_to_unpin)
        print(f"Unpinned object: {obj_to_unpin}")
        print(f"Currently pinned objects: {list(pinned_objects)}")
    else:
        print("No pinned object is currently enabled")


def list_pinned():
    """
    DESCRIPTION
    List all currently pinned objects.
    """
    global pinned_objects
    if pinned_objects:
        print(f"Pinned objects: {list(pinned_objects)}")
    else:
        print("No objects are currently pinned")


def clear_all_pins():
    """
    DESCRIPTION
    Clear all pinned objects.
    """
    global pinned_objects
    pinned_objects.clear()
    print("All pins cleared")


def toggle_auto_bucket(enable=None):
    """
    DESCRIPTION
    Toggle or set auto bucket mode.
    PARAMETERS
    enable: bool - True to enable, False to disable, None to toggle
    """
    global auto_bucket_mode
    if enable is None:
        auto_bucket_mode = not auto_bucket_mode
    else:
        auto_bucket_mode = bool(enable)

    status = "enabled" if auto_bucket_mode else "disabled"
    print(f"Auto bucket mode {status}")


def register_switch_command(command):
    """
    DESCRIPTION
    Register a command to be executed when switching objects.
    The command can use {object} as a placeholder for the current object name.
    
    PARAMETERS
    command: str - PyMOL command to execute. Use {object} for current object name.
    
    EXAMPLES
    register_switch_command("show sticks, {object}")
    register_switch_command("color red, {object} and name CA")
    """
    global switch_commands
    if command not in switch_commands:
        switch_commands.append(command)
        print(f"Registered switch command: {command}")
        print(f"Total registered commands: {len(switch_commands)}")
    else:
        print(f"Command already registered: {command}")


def unregister_switch_command(command):
    """
    DESCRIPTION
    Unregister a previously registered switch command.
    
    PARAMETERS
    command: str - The exact command string to remove
    """
    global switch_commands
    if command in switch_commands:
        switch_commands.remove(command)
        print(f"Unregistered switch command: {command}")
        print(f"Remaining registered commands: {len(switch_commands)}")
    else:
        print(f"Command not found in registered commands: {command}")


def list_switch_commands():
    """
    DESCRIPTION
    List all currently registered switch commands.
    """
    global switch_commands
    if switch_commands:
        print(f"Registered switch commands ({len(switch_commands)}):")
        for i, command in enumerate(switch_commands, 1):
            print(f"  {i}. {command}")
    else:
        print("No switch commands are currently registered")


def clear_switch_commands():
    """
    DESCRIPTION
    Clear all registered switch commands.
    """
    global switch_commands
    count = len(switch_commands)
    switch_commands.clear()
    print(f"Cleared {count} switch commands")


def execute_switch_commands(object_name):
    """
    DESCRIPTION
    Execute all registered switch commands for the given object.
    
    PARAMETERS
    object_name: str - The name of the current object
    """
    global switch_commands
    
    for command in switch_commands:
        try:
            # Replace {object} placeholder with actual object name
            formatted_command = command.format(object=object_name)
            print(f"Executing: {formatted_command}")
            cmd.do(formatted_command.strip("\"").strip("\'"))
        except Exception as e:
            print(f"Error executing switch command '{command}': {e}")


def register_show_sticks():
    """
    DESCRIPTION
    Convenience function to register showing sticks for each switched object.
    """
    register_switch_command("show sticks, {object}")


def register_show_cartoon():
    """
    DESCRIPTION
    Convenience function to register showing cartoon for each switched object.
    """
    register_switch_command("show cartoon, {object}")


def register_hide_all():
    """
    DESCRIPTION
    Convenience function to register hiding all representations for each switched object.
    """
    register_switch_command("hide everything, {object}")


def load_by_path(path=".", pattern=r"^.+pdb|.+cif$", bucket_size=10):
    """
    DESCRIPTION
    Load PDB files in the specified directory using bucket mode by default.
    PARAMETERS
    path: str - The directory path containing PDB files (default: current directory).
    pattern: str - The regex pattern to match PDB files (default: match all PDB files).
    bucket_size: int - The number of files to load in each bucket (default: 10).
    """
    global current_index, current_path, loaded_steps, reg_pattern, bucket_loader
    current_path = path

    # 更新bucket_size参数
    setup_loader(path=path, pattern=pattern, group_size=bucket_size)

    print(f"Loading files from {path} in bucket mode (bucket_size={bucket_size})")

    # 使用bucket模式加载
    bucket_loader = load_by_bucket(current_path)
    next(bucket_loader)


def take_step():
    """
    DESCRIPTION
    Iterate through loaded PDB files, enabling one and disabling others.
    """
    global loaded_steps, current_index, pinned_objects, switch_commands
    while True:
        non_pinned_steps = [
            obj for obj in cmd.get_object_list() if obj not in pinned_objects
        ]
        if not non_pinned_steps:
            print("No non-pinned objects available")
            return

        step = non_pinned_steps[current_index]
        print(f"Loading {step}...")

        # 禁用所有非固定对象
        for obj in non_pinned_steps:
            cmd.disable(obj)

        # 启用当前对象和所有固定对象
        cmd.enable(step)
        for pinned in pinned_objects:
            if pinned in cmd.get_object_list():
                cmd.enable(pinned)

        # 执行注册的切换命令
        execute_switch_commands(step)

        cmd.zoom()
        yield step


@cmd.set_key("right")
def step_forward():
    """
    DESCRIPTION
    Step forward through loaded PDB files with smart bucket switching.
    """
    smart_step_forward()


@cmd.set_key("left")
def step_backward():
    """
    DESCRIPTION
    Step backward through loaded PDB files with smart bucket switching.
    """
    smart_step_backward()


def refresh_current_idx():
    """
    Refresh the current index based on the enabled or loaded objects.
    """
    global current_index, pinned_objects
    non_pinned_objects = [
        obj for obj in cmd.get_object_list() if obj not in pinned_objects
    ]
    enabled_objects = cmd.get_names("objects", 0, selection="(enabled)")
    enabled_non_pinned = [obj for obj in enabled_objects if obj not in pinned_objects]

    if enabled_non_pinned and non_pinned_objects:
        current_index = non_pinned_objects.index(enabled_non_pinned[0])
    elif non_pinned_objects:
        current_index = 0
    else:
        current_index = -1
        print("No non-pinned objects are currently loaded.")


def get_current_object():
    """
    获取当前启用的非固定对象
    """
    global pinned_objects
    enabled_objects = cmd.get_names("objects", 0, selection="(enabled)")
    enabled_non_pinned = [obj for obj in enabled_objects if obj not in pinned_objects]

    if enabled_non_pinned:
        return enabled_non_pinned[0]
    else:
        # 如果没有启用的非固定对象，返回第一个非固定对象
        non_pinned_objects = [
            obj for obj in cmd.get_object_list() if obj not in pinned_objects
        ]
        return non_pinned_objects[0] if non_pinned_objects else None


@cmd.set_key("CTSH-S")
def save_selected():
    """
    DESCRIPTION
    Save the currently selected PDB file to a 'selected' subdirectory.
    """
    global current_path
    selected_dir = os.path.join(current_path, "selected")
    os.makedirs(selected_dir, exist_ok=True)

    current_object = get_current_object()
    if current_object is None:
        print("No object available to save")
        return

    save_path = os.path.join(selected_dir, f"{current_object}.pdb")
    print(f"Saving {current_object} to {save_path}")
    if os.path.exists(save_path):
        print(f"File {save_path} already exists. Overwrite....")
    cmd.save(save_path, current_object)


@cmd.set_key("CTSH-D")
def unselect_current():
    """
    DESCRIPTION
    Remove the currently displayed PDB file from the 'selected' subdirectory.
    """
    global current_path
    selected_dir = os.path.join(current_path, "selected")
    if not os.path.exists(selected_dir):
        print("No 'selected' directory found")
        return

    current_object = get_current_object()
    if current_object is None:
        print("No object available to unselect")
        return

    selected_path = os.path.join(selected_dir, f"{current_object}.pdb")

    if os.path.exists(selected_path):
        try:
            os.remove(selected_path)
            print(f"Removed {current_object} from selected directory: {selected_path}")
        except OSError as e:
            print(f"Error removing file {selected_path}: {e}")
    else:
        print(f"File {current_object}.pdb not found in selected directory")


def list_selected():
    """
    DESCRIPTION
    List all PDB files in the 'selected' subdirectory.
    """
    global current_path
    selected_dir = os.path.join(current_path, "selected")
    if not os.path.exists(selected_dir):
        print("No 'selected' directory found")
        return

    selected_files = [f for f in os.listdir(selected_dir) if f.endswith(".pdb")]
    if selected_files:
        print(f"Selected files ({len(selected_files)}):")
        for i, file in enumerate(selected_files, 1):
            print(f"  {i}. {file}")
    else:
        print("No files in selected directory")


def clear_selected():
    """
    DESCRIPTION
    Remove all PDB files from the 'selected' subdirectory.
    """
    global current_path
    selected_dir = os.path.join(current_path, "selected")
    if not os.path.exists(selected_dir):
        print("No 'selected' directory found")
        return

    selected_files = [f for f in os.listdir(selected_dir) if f.endswith(".pdb")]
    if not selected_files:
        print("No files to clear in selected directory")
        return

    removed_count = 0
    for file in selected_files:
        file_path = os.path.join(selected_dir, file)
        try:
            os.remove(file_path)
            removed_count += 1
        except OSError as e:
            print(f"Error removing file {file_path}: {e}")

    print(f"Removed {removed_count} files from selected directory")


def is_selected():
    """
    DESCRIPTION
    Check if the currently displayed PDB file is in the 'selected' subdirectory.
    """
    global current_path
    selected_dir = os.path.join(current_path, "selected")
    if not os.path.exists(selected_dir):
        return False

    current_object = get_current_object()
    if current_object is None:
        print("No current object to check")
        return False

    selected_path = os.path.join(selected_dir, f"{current_object}.pdb")
    is_sel = os.path.exists(selected_path)

    status = "selected" if is_sel else "not selected"
    print(f"Current object {current_object} is {status}")
    return is_sel


# Register the commands in PyMOL
cmd.extend("loadpath", load_by_path)
cmd.extend("step", step_forward)
cmd.extend("back", step_backward)
cmd.extend("save_select", save_selected)
cmd.extend("unselect", unselect_current)
cmd.extend("list_selected", list_selected)
cmd.extend("clear_selected", clear_selected)
cmd.extend("is_selected", is_selected)
cmd.extend("next_bucket", next_bucket)
cmd.extend("prev_bucket", prev_bucket)
cmd.extend("setup_loader", setup_loader)
cmd.extend("pin", pin_current)
cmd.extend("unpin", unpin_current)
cmd.extend("list_pins", list_pinned)
cmd.extend("clear_pins", clear_all_pins)
cmd.extend("auto_bucket", toggle_auto_bucket)
cmd.extend("register_switch_cmd", register_switch_command)
cmd.extend("unregister_switch_cmd", unregister_switch_command)
cmd.extend("list_switch_cmds", list_switch_commands)
cmd.extend("clear_switch_cmds", clear_switch_commands)
cmd.extend("reg_show_sticks", register_show_sticks)
cmd.extend("reg_show_cartoon", register_show_cartoon)
cmd.extend("reg_hide_all", register_hide_all)
